    /**
     * Advanced builder for endpoint for the Spring Redis component.
     */
    public interface AdvancedRedisEndpointBuilder
            extends
                AdvancedRedisEndpointConsumerBuilder,
                AdvancedRedisEndpointProducerBuilder {
        default RedisEndpointBuilder basic() {
            return (RedisEndpointBuilder) this;
        }

        /**
         * An ObjectInputFilter pattern, in jdk.serialFilter syntax, that the
         * default JdkSerializationRedisSerializer applies when it deserializes
         * a value: the body of a message that the consumer receives, and a
         * value that the producer reads with the RedisTemplate that the
         * endpoint creates. If not set, the JVM-wide jdk.serialFilter is used
         * when present, otherwise a default filter that rejects java.net.**,
         * allows only java.**, javax.** and org.apache.camel.**, and limits the
         * depth, references and size of the object graph. Not used when
         * serializer is set.
         * 
         * The option is a: <code>java.lang.String</code> type.
         * 
         * Group: security
         * 
         * @param deserializationFilter the value to set
         * @return the dsl builder
         */
        default AdvancedRedisEndpointBuilder deserializationFilter(String deserializationFilter) {
            doSetProperty("deserializationFilter", deserializationFilter);
            return this;
        }
    }

    public interface RedisBuilders {
        /**
         * Spring Redis (camel-spring-redis)
         * Send commands to Redis and receive the messages of Redis Pub/Sub
         * channels, using Spring Data Redis.
         * 
         * Category: cache
         * Since: 2.11
         * Maven coordinates: org.apache.camel:camel-spring-redis
         * 
         * @return the dsl builder for the headers' name.
         */
        default RedisHeaderNameBuilder springRedis() {
            return RedisHeaderNameBuilder.INSTANCE;
        }
        /**
         * Spring Redis (camel-spring-redis)
         * Send commands to Redis and receive the messages of Redis Pub/Sub
         * channels, using Spring Data Redis.
         * 
         * Category: cache
         * Since: 2.11
         * Maven coordinates: org.apache.camel:camel-spring-redis
         * 
         * Syntax: <code>spring-redis:host:port</code>
         * 
         * Path parameter: host (required)
         * The host name or IP address of the Redis server. The endpoint
         * connects to it with the JedisConnectionFactory that it creates when
         * connectionFactory is not set, and does not use it otherwise. If not
         * set, localhost is used.
         * 
         * Path parameter: port (required)
         * The port of the Redis server. The endpoint connects to it with the
         * JedisConnectionFactory that it creates when connectionFactory is not
         * set, and does not use it otherwise. If not set, 6379 is used.
         * 
         * @param path host:port
         * @return the dsl builder
         */
        default RedisEndpointBuilder springRedis(String path) {
            return RedisEndpointBuilderFactory.endpointBuilder("spring-redis", path);
        }
        /**
         * Spring Redis (camel-spring-redis)
         * Send commands to Redis and receive the messages of Redis Pub/Sub
         * channels, using Spring Data Redis.
         * 
         * Category: cache
         * Since: 2.11
         * Maven coordinates: org.apache.camel:camel-spring-redis
         * 
         * Syntax: <code>spring-redis:host:port</code>
         * 
         * Path parameter: host (required)
         * The host name or IP address of the Redis server. The endpoint
         * connects to it with the JedisConnectionFactory that it creates when
         * connectionFactory is not set, and does not use it otherwise. If not
         * set, localhost is used.
         * 
         * Path parameter: port (required)
         * The port of the Redis server. The endpoint connects to it with the
         * JedisConnectionFactory that it creates when connectionFactory is not
         * set, and does not use it otherwise. If not set, 6379 is used.
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path host:port
         * @return the dsl builder
         */
        default RedisEndpointBuilder springRedis(String componentName, String path) {
            return RedisEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
